'use client';
import Image from 'next/image';
import { useState } from 'react';
import { renderUrl, type RenderAngle } from '@/lib/format';

/**
 * Representative studio render of a product (generated by `npm run renders`).
 * Falls back to a quiet placeholder if a render has not been generated yet.
 */
export function ProductImage({
  slug,
  colorId,
  angle = 'hero',
  alt,
  sizes = '(max-width: 768px) 50vw, 25vw',
  priority,
  className = '',
}: {
  slug: string;
  colorId: string;
  angle?: RenderAngle;
  alt: string;
  sizes?: string;
  priority?: boolean;
  className?: string;
}) {
  const [failed, setFailed] = useState(false);
  if (failed)
    return (
      <div className={`grid h-full w-full place-items-center ${className}`} role="img" aria-label={alt}>
        <span className="eyebrow text-muted">Render pending</span>
      </div>
    );
  return (
    <Image
      src={renderUrl(slug, colorId, angle)}
      alt={alt}
      fill
      sizes={sizes}
      priority={priority}
      quality={90}
      className={`object-contain ${className}`}
      onError={() => setFailed(true)}
      draggable={false}
    />
  );
}
